struct nglQuad { char data[0x70]; };
void nglListAddQuad(nglQuad *);
class TextString { public: void changeText(const char *); void Draw(); };
extern "C" int sprintf(char *, const char *, ...);

class IGOIconManager {
public:
  class IconResource { char padding[12]; public: unsigned char timesDisplayed; };
  class Icon {
    char padding[0x40];
  public:
    IconResource *resource;
    char padding2[0x30];
    bool show;
    void Draw();
  };
  struct IconSpawn { char padding[0x38]; int buttonDisplay; float buttonDelay; };
private:
  nglQuad glowQuad[5], iceQuad[5], chainQuad[5], buttonQuad[8];
  Icon effectIcons[5];
  char padding0[0x294];
  Icon *icons;
  char padding1[0xc];
  int numIcons;
  char padding2[0x8];
  int activeIcon;
  char padding3[0x8];
  unsigned char numEffectIcons;
  char padding4[0x1f];
  float buttonTimer;
  int prepareFailure;
  bool failure, drawButtons, showTimer, nextEnable;
  unsigned char numChains, numFrozen, numGlowing;
  char padding5;
  float time, timeLastQueueChange;
  char padding6[0x40];
  int currentSpawn;
  IconSpawn iconSpawns[8];
  Icon nextIcon;
  float spawnTimer;
  int numButtons, numEffectPadding;
  int scoreBonuses[5];
  bool prepPop;
  TextString *timerText, *scoreText, *scoreTextEffect;
public:
  void Draw(void);
};

void IGOIconManager::Draw(void)
{
  int i;

  timeLastQueueChange = time;

  if(!failure)
  {
    // Draw glowing textures
    for(i=0; i<numGlowing; i++)
      nglListAddQuad(&glowQuad[i]);

    // Draw Icons
	  for (i = 0; i < numIcons; i++)
		  icons[i].Draw();
    if(nextEnable && nextIcon.show)
      nextIcon.Draw();

    // Draw Effect Icons
	  for (i = 0; i < numEffectIcons; i++)
		  effectIcons[i].Draw();

    // Draw frozen textures
    for(i=0; i<numFrozen; i++)
      nglListAddQuad(&iceQuad[i]);

    // Draw chain links
    for(i=0; i<numChains; i++)
      nglListAddQuad(&chainQuad[i]);

    // Draw Buttons
    if(activeIcon < numIcons && icons[activeIcon].resource->timesDisplayed < iconSpawns[currentSpawn].buttonDisplay &&
       buttonTimer >= iconSpawns[currentSpawn].buttonDelay)
      drawButtons = true;
    else
      drawButtons = false;

    if(drawButtons)
    {
	    for (i = 0; i<numButtons; i++)
		    nglListAddQuad(&buttonQuad[i]);
    }

    // Draw Spawn Countdown
    char text2[16];
    sprintf(text2, "%0.1f", spawnTimer);
	  timerText->changeText(text2);
    if(nextEnable && showTimer)
      timerText->Draw();
  }

  // Draw Score Bonus text
  if(numEffectIcons > 0 && scoreBonuses[numEffectIcons-1] != 0 && !prepareFailure && !failure )
  {
	  scoreText->Draw();
    if(prepPop)
      scoreTextEffect->Draw();
  }
}
